//! Golden tests against OpenSSL ACVP vectors (FIPS 203).
//!
//! Vectors extracted from OpenSSL 3.5.8
//! `test/recipes/30-test_evp_data/evppkey_ml_kem_*.txt`.

use super::*;
use alloc::vec::Vec;

fn hex_to_bytes(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

// ---- keygen 512 ----
#[test]
fn acvp_keygen_512() {
    {
        let seed = hex_to_bytes("1eb4400a01629d517974e2cd85b9def59082de508e6f9c2b0e341e12965955ca1a394111163803fe2e8519c335a6867556338eadafa22b5fc557430560ccd693");
        let mut seed_arr = [0u8; 64];
        seed_arr.copy_from_slice(&seed);
        let (pk, sk) = keygen(MlKemVariant::MlKem512, &seed_arr).unwrap();
        assert_eq!(pk.to_bytes(), hex_to_bytes("").as_slice(), "keygen 512 #0 pub");
        assert_eq!(sk.to_bytes(), hex_to_bytes("").as_slice(), "keygen 512 #0 priv");
    }
    {
        let seed = hex_to_bytes("47877987835ef38823a23b37ca4ce2844bc017f9a1efadf8c5d73cb5562c81a461846347fde6757082e3d56ea060ceb773d5f38a84b8d8aacf776ef9cf766cf8");
        let mut seed_arr = [0u8; 64];
        seed_arr.copy_from_slice(&seed);
        let (pk, sk) = keygen(MlKemVariant::MlKem512, &seed_arr).unwrap();
        assert_eq!(pk.to_bytes(), hex_to_bytes("").as_slice(), "keygen 512 #1 pub");
        assert_eq!(sk.to_bytes(), hex_to_bytes("").as_slice(), "keygen 512 #1 priv");
    }
    {
        let seed = hex_to_bytes("daaa521d7780e6c72d3a6626b8d5df8abbc5ae44a9abc647576035a9a6a9db4d2056fb9b4e06a790f1d1538ba6d81de1953902d9d50ea8d646a0231f11d89981");
        let mut seed_arr = [0u8; 64];
        seed_arr.copy_from_slice(&seed);
        let (pk, sk) = keygen(MlKemVariant::MlKem512, &seed_arr).unwrap();
        assert_eq!(pk.to_bytes(), hex_to_bytes("").as_slice(), "keygen 512 #2 pub");
        assert_eq!(sk.to_bytes(), hex_to_bytes("").as_slice(), "keygen 512 #2 priv");
    }
}

