// ---- encapsulate 512 ----
#[test]
fn acvp_encap_512() {
    {
        let pk = MlKemPublicKey::from_bytes(MlKemVariant::MlKem512, &hex_to_bytes("")).unwrap();
        let mut m = [0u8; 32];
        m.copy_from_slice(&hex_to_bytes("147c03f7a5bebba406c8fae1874d7f13c80efe79a3a9a874cc09fe76f6997615"));
        let (ct, ss_out) = encapsulate(&pk, &m).unwrap();
        assert_eq!(ct, hex_to_bytes(""), "encap 512 #0 ct");
        assert_eq!(ss_out.as_slice(), hex_to_bytes("319839e82ab6b222de7b619e80da8391522bbb37677018494a4742c53f9abfdf").as_slice(), "encap 512 #0 ss");
    }
    {
        let pk = MlKemPublicKey::from_bytes(MlKemVariant::MlKem512, &hex_to_bytes("")).unwrap();
        let mut m = [0u8; 32];
        m.copy_from_slice(&hex_to_bytes("cde797df8ce67231f6c5d15811843e01eb2ab84c7490931240822adbddd72046"));
        let (ct, ss_out) = encapsulate(&pk, &m).unwrap();
        assert_eq!(ct, hex_to_bytes(""), "encap 512 #1 ct");
        assert_eq!(ss_out.as_slice(), hex_to_bytes("3806942c857ab9bf77b1db8d57ec9dca0ffbf6f156f2e250d8b88cc2a74fa1a7").as_slice(), "encap 512 #1 ss");
    }
    {
        let pk = MlKemPublicKey::from_bytes(MlKemVariant::MlKem512, &hex_to_bytes("")).unwrap();
        let mut m = [0u8; 32];
        m.copy_from_slice(&hex_to_bytes("f43f68fbd694f0a6d307297110ecd4739876489fdf07eb9b03364e2ed0ff96e9"));
        let (ct, ss_out) = encapsulate(&pk, &m).unwrap();
        assert_eq!(ct, hex_to_bytes(""), "encap 512 #2 ct");
        assert_eq!(ss_out.as_slice(), hex_to_bytes("a1e73a1ebd907a6f176acf808b0d0412d31cff0e9d800a732e1e96bd9f8d7ebb").as_slice(), "encap 512 #2 ss");
    }
}

