// ---- roundtrip and error handling ----
#[test]
fn encaps_decaps_roundtrip() {
    for variant in [
        MlKemVariant::MlKem512,
        MlKemVariant::MlKem768,
        MlKemVariant::MlKem1024,
    ] {
        let mut seed = [0u8; 64];
        for (i, b) in seed.iter_mut().enumerate() {
            *b = (i as u8).wrapping_mul(17).wrapping_add(3);
        }
        let (pk, sk) = keygen(variant, &seed).unwrap();
        for m_byte in [0u8, 1u8, 0xA5u8, 0xFFu8] {
            let m = [m_byte; 32];
            let (ct, ss1) = encapsulate(&pk, &m).unwrap();
            assert_eq!(ct.len(), variant.ciphertext_len());
            let ss2 = decapsulate(&sk, &ct).unwrap();
            assert_eq!(ss1, ss2, "roundtrip {:?} m={:#04x}", variant, m_byte);
        }
    }
}

#[test]
fn decap_rejects_wrong_length() {
    let seed = [42u8; 64];
    let (pk, sk) = keygen(MlKemVariant::MlKem768, &seed).unwrap();
    let m = [7u8; 32];
    let (mut ct, ss) = encapsulate(&pk, &m).unwrap();
    assert_eq!(decapsulate(&sk, &ct).unwrap(), ss);
    ct.pop();
    assert!(decapsulate(&sk, &ct).is_err(), "short ct must be rejected");
    let long = alloc::vec![0u8; MlKemVariant::MlKem768.ciphertext_len() + 1];
    assert!(decapsulate(&sk, &long).is_err(), "long ct must be rejected");
    let empty: alloc::vec::Vec<u8> = alloc::vec::Vec::new();
    assert!(decapsulate(&sk, &empty).is_err(), "empty ct must be rejected");
    let half = alloc::vec![0u8; MlKemVariant::MlKem768.ciphertext_len() / 2];
    assert!(decapsulate(&sk, &half).is_err(), "half ct must be rejected");
}

#[test]
fn decap_implicit_rejection_differs() {
    // A well-formed-length but corrupted ciphertext must yield a shared
    // secret different from the honest one (FIPS 203 implicit rejection).
    let seed = [99u8; 64];
    let (pk, sk) = keygen(MlKemVariant::MlKem512, &seed).unwrap();
    let m = [1u8; 32];
    let (mut ct, ss) = encapsulate(&pk, &m).unwrap();
    ct[0] ^= 1;
    let ss_bad = decapsulate(&sk, &ct).unwrap();
    assert_ne!(ss_bad, ss);
}

#[test]
fn key_bytes_roundtrip() {
    for variant in [
        MlKemVariant::MlKem512,
        MlKemVariant::MlKem768,
        MlKemVariant::MlKem1024,
    ] {
        let seed = [0x5Au8; 64];
        let (pk, sk) = keygen(variant, &seed).unwrap();
        let pk2 = MlKemPublicKey::from_bytes(variant, pk.to_bytes()).unwrap();
        let sk2 = MlKemPrivateKey::from_bytes(variant, sk.to_bytes()).unwrap();
        assert_eq!(pk.to_bytes(), pk2.to_bytes());
        assert_eq!(sk.to_bytes(), sk2.to_bytes());
    }
}

